/*
A legal-entity registry: companies, registrations, industries, locations, positions/appointments,
and the ownership/affiliation graph. Reads gate on `company.read`; company/registration/industry/
location/ownership writes on `company.manage`; position/appointment writes on
`company.position.manage`; catalog-entry writes on `company.catalog.manage`. Writes are audited
in-process (D-Audit).
*/
type CompanyServiceClientWithAuth interface {
	ListLegalForms(ctx context.Context) (LegalFormList, error)
	UpsertLegalForm(ctx context.Context, requestArg UpsertLegalFormRequest) (LegalForm, error)
	ListRegistrationSchemes(ctx context.Context) (RegistrationSchemeList, error)
	UpsertRegistrationScheme(ctx context.Context, requestArg UpsertSchemeRequest) (RegistrationScheme, error)
	ListIndustryClasses(ctx context.Context) (IndustryClassList, error)
	UpsertIndustryClass(ctx context.Context, requestArg UpsertIndustryClassRequest) (IndustryClass, error)
	CreateCompany(ctx context.Context, requestArg CreateCompanyRequest) (Company, error)
	/*
	   List companies, token-paginated, optionally filtered by the facet vocabulary (M58 ticket 5 /
	   D-ObjectFacets). Shadow-gated: a company IS a `company`-domain tenant organization (M41 /
	   D-UnifiedOrgGraph), so it carries that organization's public/shadow bit and is trimmed by
	   the same rule `listOrganizations` applies. Gated by company.read.

	   Every filter arg here is also an arg of `companyStats`, and a chart segment's key is a
	   usable value for the arg it came from — that is what makes a dashboard and a list two
	   renderings of one request state.
	*/
	ListCompanies(ctx context.Context, queryArg *string, legalFormArg *string, ownershipCategoryArg *string, countryIdArg *string, industryClassArg *string, foundedOnFromArg *string, foundedOnToArg *string, stateArg *string, pageSizeArg *int, pageTokenArg *string) (CompanyPage, error)
	/*
	   Facet distributions over the company registry — the dashboard half of the company facet
	   vocabulary (M58 ticket 5 / D-ObjectFacets). Takes exactly the filter args `listCompanies`
	   takes, minus paging, so a dashboard and a list are two renderings of one request state.

	   The path is `/stats/companies` rather than `/companies/stats` because the server's router
	   rejects a literal path segment that is a sibling of `{companyId}` — see the route-conflict
	   guard in `internal/platform/transport`.
	*/
	CompanyStats(ctx context.Context, facetsArg *string, queryArg *string, legalFormArg *string, ownershipCategoryArg *string, countryIdArg *string, industryClassArg *string, foundedOnFromArg *string, foundedOnToArg *string, stateArg *string) (CompanyStats, error)
	GetCompany(ctx context.Context, companyIdArg string) (Company, error)
	UpdateCompany(ctx context.Context, companyIdArg string, requestArg UpdateCompanyRequest) (Company, error)
	DeleteCompany(ctx context.Context, companyIdArg string) error
	ListRegistrations(ctx context.Context, companyIdArg string) (RegistrationList, error)
	AddRegistration(ctx context.Context, companyIdArg string, requestArg UpsertRegistrationRequest) (Registration, error)
	UpdateRegistration(ctx context.Context, registrationIdArg string, requestArg UpsertRegistrationRequest) (Registration, error)
	DeleteRegistration(ctx context.Context, registrationIdArg string) error
	ListIndustries(ctx context.Context, companyIdArg string) (IndustryAssignmentList, error)
	AssignIndustry(ctx context.Context, companyIdArg string, requestArg AssignIndustryRequest) (IndustryAssignment, error)
	RemoveIndustry(ctx context.Context, assignmentIdArg string) error
	ListCompanyLocations(ctx context.Context, companyIdArg string) (CompanyLocationList, error)
	AddCompanyLocation(ctx context.Context, companyIdArg string, requestArg AddCompanyLocationRequest) (CompanyLocation, error)
	RemoveCompanyLocation(ctx context.Context, companyLocationIdArg string) error
	CreatePosition(ctx context.Context, companyIdArg string, requestArg CreatePositionRequest) (CompanyPosition, error)
	ListPositions(ctx context.Context, companyIdArg string, stateArg *string, pageSizeArg *int, pageTokenArg *string) (CompanyPositionPage, error)
	GetPosition(ctx context.Context, positionIdArg string) (CompanyPosition, error)
	UpdatePosition(ctx context.Context, positionIdArg string, requestArg UpdatePositionRequest) (CompanyPosition, error)
	AbolishPosition(ctx context.Context, positionIdArg string) (CompanyPosition, error)
	// Fill a vacant position. Returns Company:PositionAlreadyFilled if already filled.
	FillPosition(ctx context.Context, positionIdArg string, requestArg FillPositionRequest) (Appointment, error)
	EndAppointment(ctx context.Context, appointmentIdArg string, requestArg EndAppointmentRequest) (Appointment, error)
	GetOwnershipGraph(ctx context.Context, companyIdArg string) (OwnershipGraph, error)
	RecordFounding(ctx context.Context, companyIdArg string, requestArg RecordFoundingRequest) (Founding, error)
	RemoveFounding(ctx context.Context, foundingIdArg string) error
	RecordShareholding(ctx context.Context, companyIdArg string, requestArg RecordShareholdingRequest) (Shareholding, error)
	RemoveShareholding(ctx context.Context, shareholdingIdArg string) error
	RecordBeneficiary(ctx context.Context, companyIdArg string, requestArg RecordBeneficiaryRequest) (Beneficiary, error)
	RemoveBeneficiary(ctx context.Context, beneficiaryIdArg string) error
	RecordSuccession(ctx context.Context, companyIdArg string, requestArg RecordSuccessionRequest) (Succession, error)
	RemoveSuccession(ctx context.Context, successionIdArg string) error
	RecordBranch(ctx context.Context, companyIdArg string, requestArg RecordBranchRequest) (Branch, error)
	RemoveBranch(ctx context.Context, branchIdArg string) error
	// Read-only view of a person's company links (employment, founding, ownership, beneficiary-of).
	ListPersonCompanyAffiliations(ctx context.Context, personIdArg string) (PersonCompanyAffiliations, error)
}

